mapper.insert:
INSERT INTO authority_investigation_head (
    investigation_id, incident_id, aggregate_version, status, current_run_id,
    steps_used, tool_calls_used, no_progress_rounds, snapshot_json,
    snapshot_sha256, created_at, updated_at
) VALUES (
    #{investigationId}, #{incidentId}, #{aggregateVersion}, #{status}, #{currentRunId},
    #{stepsUsed}, #{toolCallsUsed}, #{noProgressRounds}, #{snapshotJson},
    #{snapshotSha256}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE authority_investigation_head
SET incident_id = #{row.incidentId}, aggregate_version = #{row.aggregateVersion},
    status = #{row.status}, current_run_id = #{row.currentRunId},
    steps_used = #{row.stepsUsed}, tool_calls_used = #{row.toolCallsUsed},
    no_progress_rounds = #{row.noProgressRounds}, snapshot_json = #{row.snapshotJson},
    snapshot_sha256 = #{row.snapshotSha256}, updated_at = #{row.updatedAt}
WHERE investigation_id = #{row.investigationId}
  AND aggregate_version = #{expectedVersion}

