INSERT INTO authority_audit (
    audit_id, investigation_id, sequence_number, aggregate_version,
    audit_kind, entity_id, reason_code, occurred_at
) VALUES (
    #{auditId}, #{investigationId}, #{sequenceNumber}, #{aggregateVersion},
