mapper.select:
SELECT audit_id, investigation_id, sequence_number, aggregate_version,
       audit_kind, entity_id, reason_code, occurred_at
FROM authority_audit
WHERE investigation_id = #{investigationId} AND sequence_number > #{afterSequence}
ORDER BY sequence_number
LIMIT #{limit}
